// PCIe_CXL_IDE_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module PCIe_CXL_IDE_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic [1:0] c_s_en,
  input logic [1:0] c_s_cm,
  input logic [6:0] c_cm_agg,
  input logic [15:0] c_s_id,
  input logic [63:0] c_s_ivfix,
  input logic  c_km_dir,
  input logic [1:0] c_km_sid,
  input logic  c_km_ks,
  input logic [1:0] c_km_sub,
  input logic  c_km_sel,
  input logic [255:0] c_km_key,
  input logic  c_km_prog,
  input logic  c_km_go,
  input logic  c_km_stop,
  input logic  c_clr,
  input logic [127:0] c_tx_data,
  input logic [4:0] c_tx_bytes,
  input logic  c_tx_hdr,
  input logic  c_tx_last,
  input logic  c_tx_ide,
  input logic [1:0] c_tx_sid,
  input logic [1:0] c_tx_sub,
  input logic [127:0] c_txo_data,
  input logic [4:0] c_txo_bytes,
  input logic [1:0] c_txo_kind,
  input logic  c_txo_last,
  input logic  c_txo_bad,
  input logic  c_txo_cm,
  input logic [127:0] c_rx_data,
  input logic [4:0] c_rx_bytes,
  input logic [1:0] c_rx_kind,
  input logic  c_rx_last,
  input logic  c_rx_cm,
  input logic [1:0] c_rx_sid,
  input logic [127:0] c_rxo_data,
  input logic [4:0] c_rxo_bytes,
  input logic [1:0] c_rxo_kind,
  input logic  c_rxo_last,
  input logic  c_rxo_bad,
  input logic  c_rxo_cm,
  input logic [1:0] c_sec_tx,
  input logic [1:0] c_sec_rx,
  input logic [1:0] c_ks_tx,
  input logic [1:0] c_ks_rx,
  input logic  c_tx_busy,
  input logic  c_rx_busy,
  input logic [2:0] c_km_code,
  input logic [2:0] c_tx_code,
  input logic [1:0] c_tx_esid,
  input logic [2:0] c_rx_code,
  input logic [7:0] c_rx_eid,
  input logic [11:0] c_kv_tx,
  input logic [11:0] c_kv_rx,
  input logic  c_tx_valid,
  input logic  c_tx_ready,
  input logic  c_txo_valid,
  input logic  c_txo_ready,
  input logic  c_rx_valid,
  input logic  c_rx_ready,
  input logic  c_rxo_valid,
  input logic  c_rxo_ready,
  input logic  c_tx_done,
  input logic  c_tx_err,
  input logic  c_rx_done,
  input logic  c_rx_err,
  input logic  c_km_err
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 41;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:40];          // model of every stored word
  logic [10:0] m_set;                // interrupt bits set this clock
  logic [31:0] m_pulse_CMD;
  logic m_state_TX;          // full / valid pulse / available
  logic m_state_TXO;          // full / valid pulse / available
  logic m_state_RX;          // full / valid pulse / available
  logic m_state_RXO;          // full / valid pulse / available

  always_comb begin
    m_set = '0;
    if (c_tx_done) m_set[0] = 1'b1;
    if (c_tx_err) m_set[1] = 1'b1;
    if (c_rx_done) m_set[2] = 1'b1;
    if (c_rx_err) m_set[3] = 1'b1;
    if (c_km_err) m_set[4] = 1'b1;
    if (m_state_TX && c_tx_ready) m_set[5] = 1'b1;
    if (m_wr && m_map && (m_idx == 19 || m_idx == 20 || m_idx == 21 || m_idx == 22 || m_idx == 23) && m_state_TX) m_set[6] = 1'b1;
    if (c_txo_valid && !m_state_TXO) m_set[7] = 1'b1;
    if (c_txo_valid && m_state_TXO && (m_rd && m_map && m_idx == 28)) m_set[7] = 1'b1;
    if (m_state_RX && c_rx_ready) m_set[8] = 1'b1;
    if (m_wr && m_map && (m_idx == 29 || m_idx == 30 || m_idx == 31 || m_idx == 32 || m_idx == 33) && m_state_RX) m_set[9] = 1'b1;
    if (c_rxo_valid && !m_state_RXO) m_set[10] = 1'b1;
    if (c_rxo_valid && m_state_RXO && (m_rd && m_map && m_idx == 38)) m_set[10] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h0;
      m_w[6] <= 32'h0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
