      if (m_state_TX && c_tx_ready) m_state_TX <= 0;
      if (c_txo_valid && (!m_state_TXO || (m_rd && m_map && m_idx == 28))) begin
        m_w[24] <= (32'(c_txo_data[31:0]) << 0);
        m_w[25] <= (32'(c_txo_data[63:32]) << 0);
        m_w[26] <= (32'(c_txo_data[95:64]) << 0);
        m_w[27] <= (32'(c_txo_data[127:96]) << 0);
        m_w[28] <= (32'(c_txo_bytes[4:0]) << 0) | (32'(c_txo_kind[1:0]) << 5) | (32'(c_txo_last) << 7) | (32'(c_txo_bad) << 8) | (32'(c_txo_cm) << 9);
        m_state_TXO <= 1;
