      if (m_wr && m_map && m_idx == 29 && !m_state_RX) m_w[29] <= ((m_w[29] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 30 && !m_state_RX) m_w[30] <= ((m_w[30] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 31 && !m_state_RX) m_w[31] <= ((m_w[31] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 32 && !m_state_RX) m_w[32] <= ((m_w[32] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 33 && !m_state_RX) m_w[33] <= ((m_w[33] & ~m_be) | (PWDATA & m_be)) & 32'h7FF;
      if (m_wr && m_map && m_idx == 33 && !m_state_RX) m_state_RX <= 1;
      if (m_state_RX && c_rx_ready) m_state_RX <= 0;
      if (c_rxo_valid && (!m_state_RXO || (m_rd && m_map && m_idx == 38))) begin
        m_w[34] <= (32'(c_rxo_data[31:0]) << 0);
        m_w[35] <= (32'(c_rxo_data[63:32]) << 0);
        m_w[36] <= (32'(c_rxo_data[95:64]) << 0);
        m_w[37] <= (32'(c_rxo_data[127:96]) << 0);
        m_w[38] <= (32'(c_rxo_bytes[4:0]) << 0) | (32'(c_rxo_kind[1:0]) << 5) | (32'(c_rxo_last) << 7) | (32'(c_rxo_bad) << 8) | (32'(c_rxo_cm) << 9);
        m_state_RXO <= 1;
      end else if ((m_rd && m_map && m_idx == 38)) m_state_RXO <= 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h49440100;
      1: return m_w[1];
      2: return m_w[2];
      3: return 32'({m_state_RXO, m_state_RX, m_state_TXO, m_state_TX});
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return m_w[9];
      10: return 0;
      11: return 0;
      12: return 0;
      13: return 0;
      14: return 0;
      15: return 0;
      16: return 0;
      17: return 0;
      18: return 0;
      19: return m_w[19];
      20: return m_w[20];
      21: return m_w[21];
      22: return m_w[22];
      23: return m_w[23];
      24: return m_w[24];
      25: return m_w[25];
      26: return m_w[26];
      27: return m_w[27];
      28: return m_w[28];
      29: return m_w[29];
      30: return m_w[30];
      31: return m_w[31];
      32: return m_w[32];
      33: return m_w[33];
      34: return m_w[34];
      35: return m_w[35];
      36: return m_w[36];
      37: return m_w[37];
      38: return m_w[38];
      39: return (32'(c_sec_tx) << 0) | (32'(c_sec_rx) << 2) | (32'(c_ks_tx) << 4) | (32'(c_ks_rx) << 6) | (32'(c_tx_busy) << 8) | (32'(c_rx_busy) << 9) | (32'(c_km_code) << 10) | (32'(c_tx_code) << 13) | (32'(c_tx_esid) << 16) | (32'(c_rx_code) << 18) | (32'(c_rx_eid) << 21);
      40: return (32'(c_kv_tx) << 0) | (32'(c_kv_rx) << 12);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][10:0] & m_w[2][10:0]))
  `SVA_INV(a_core_s_en, c_s_en == m_w[5][1:0])
  `SVA_INV(a_core_s_cm, c_s_cm == m_w[5][3:2])
  `SVA_INV(a_core_cm_agg, c_cm_agg == m_w[5][10:4])
  `SVA_INV(a_core_s_id, c_s_id == m_w[6][15:0])
  `SVA_INV(a_core_s_ivfix_31_0, c_s_ivfix[31:0] == m_w[7][31:0])
  `SVA_INV(a_core_s_ivfix_63_32, c_s_ivfix[63:32] == m_w[8][31:0])
  `SVA_INV(a_core_km_dir, c_km_dir == m_w[9][0:0])
  `SVA_INV(a_core_km_sid, c_km_sid == m_w[9][2:1])
  `SVA_INV(a_core_km_ks, c_km_ks == m_w[9][3:3])
  `SVA_INV(a_core_km_sub, c_km_sub == m_w[9][5:4])
  `SVA_INV(a_core_km_sel, c_km_sel == m_w[9][6:6])
  `SVA_INV(a_core_km_key_31_0, c_km_key[31:0] == m_w[10][31:0])
  `SVA_INV(a_core_km_key_63_32, c_km_key[63:32] == m_w[11][31:0])
  `SVA_INV(a_core_km_key_95_64, c_km_key[95:64] == m_w[12][31:0])
  `SVA_INV(a_core_km_key_127_96, c_km_key[127:96] == m_w[13][31:0])
  `SVA_INV(a_core_km_key_159_128, c_km_key[159:128] == m_w[14][31:0])
  `SVA_INV(a_core_km_key_191_160, c_km_key[191:160] == m_w[15][31:0])
  `SVA_INV(a_core_km_key_223_192, c_km_key[223:192] == m_w[16][31:0])
  `SVA_INV(a_core_km_key_255_224, c_km_key[255:224] == m_w[17][31:0])
  `SVA_INV(a_core_km_prog, c_km_prog == m_pulse_CMD[0])
  `SVA_INV(a_core_km_go, c_km_go == m_pulse_CMD[1])
  `SVA_INV(a_core_km_stop, c_km_stop == m_pulse_CMD[2])
  `SVA_INV(a_core_clr, c_clr == m_pulse_CMD[3])
  `SVA_INV(a_core_tx_data_31_0, c_tx_data[31:0] == m_w[19][31:0])
  `SVA_INV(a_core_tx_data_63_32, c_tx_data[63:32] == m_w[20][31:0])
  `SVA_INV(a_core_tx_data_95_64, c_tx_data[95:64] == m_w[21][31:0])
  `SVA_INV(a_core_tx_data_127_96, c_tx_data[127:96] == m_w[22][31:0])
  `SVA_INV(a_core_tx_bytes, c_tx_bytes == m_w[23][4:0])
  `SVA_INV(a_core_tx_hdr, c_tx_hdr == m_w[23][5:5])
  `SVA_INV(a_core_tx_last, c_tx_last == m_w[23][6:6])
  `SVA_INV(a_core_tx_ide, c_tx_ide == m_w[23][7:7])
  `SVA_INV(a_core_tx_sid, c_tx_sid == m_w[23][9:8])
  `SVA_INV(a_core_tx_sub, c_tx_sub == m_w[23][11:10])
  `SVA_INV(a_core_rx_data_31_0, c_rx_data[31:0] == m_w[29][31:0])
  `SVA_INV(a_core_rx_data_63_32, c_rx_data[63:32] == m_w[30][31:0])
  `SVA_INV(a_core_rx_data_95_64, c_rx_data[95:64] == m_w[31][31:0])
  `SVA_INV(a_core_rx_data_127_96, c_rx_data[127:96] == m_w[32][31:0])
  `SVA_INV(a_core_rx_bytes, c_rx_bytes == m_w[33][4:0])
