  `SVA_INV(a_core_rx_cm, c_rx_cm == m_w[33][8:8])
  `SVA_INV(a_core_rx_sid, c_rx_sid == m_w[33][10:9])
  `SVA_INV(a_core_tx_valid, c_tx_valid == m_state_TX)
  `SVA_INV(a_core_txo_ready, c_txo_ready == (!m_state_TXO || (m_rd && m_map && m_idx == 28)))
  `SVA_INV(a_core_rx_valid, c_rx_valid == m_state_RX)
  `SVA_INV(a_core_rxo_ready, c_rxo_ready == (!m_state_RXO || (m_rd && m_map && m_idx == 38)))
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_s_en == 2'h0 && c_s_cm == 2'h0 && c_cm_agg == 7'h0 && c_s_id == 16'h0 && c_s_ivfix[31:0] == 32'h0 && c_s_ivfix[63:32] == 32'h0 && c_km_dir == 1'h0 && c_km_sid == 2'h0 && c_km_ks == 1'h0 && c_km_sub == 2'h0 && c_km_sel == 1'h0 && c_km_key[31:0] == 32'h0 && c_km_key[63:32] == 32'h0 && c_km_key[95:64] == 32'h0 && c_km_key[127:96] == 32'h0 && c_km_key[159:128] == 32'h0 && c_km_key[191:160] == 32'h0 && c_km_key[223:192] == 32'h0 && c_km_key[255:224] == 32'h0 && c_km_prog == 1'h0 && c_km_go == 1'h0 && c_km_stop == 1'h0 && c_clr == 1'h0 && c_tx_data[31:0] == 32'h0 && c_tx_data[63:32] == 32'h0 && c_tx_data[95:64] == 32'h0 && c_tx_data[127:96] == 32'h0 && c_tx_bytes == 5'h0 && c_tx_hdr == 1'h0 && c_tx_last == 1'h0 && c_tx_ide == 1'h0 && c_tx_sid == 2'h0 && c_tx_sub == 2'h0 && c_rx_data[31:0] == 32'h0 && c_rx_data[63:32] == 32'h0 && c_rx_data[95:64] == 32'h0 && c_rx_data[127:96] == 32'h0 && c_rx_bytes == 5'h0 && c_rx_kind == 2'h0 && c_rx_last == 1'h0 && c_rx_cm == 1'h0 && c_rx_sid == 2'h0 && !c_tx_valid && c_txo_ready && !c_rx_valid && c_rxo_ready)

